const KEY='it-lab-interface-v1';
export const PRESETS={dark:{bg:'#10151e',panel:'#192230',text:'#e7eef8',accent:'#91b9ff',button:'#356fe0'},light:{bg:'#edf1f7',panel:'#ffffff',text:'#19263c',accent:'#285bbb',button:'#285bbb'}};
export const FIELDS={bg:'Фон',panel:'Панели',text:'Текст',accent:'Акценты',button:'Кнопки'};
export const validColor=v=>typeof v==='string'&&/^#[0-9a-f]{6}$/i.test(v);
export function normalizeTheme(value){const mode=['dark','light','custom'].includes(value?.mode)?value.mode:'dark';return {mode,colors:Object.fromEntries(Object.keys(FIELDS).map(k=>[k,validColor(value?.colors?.[k])?value.colors[k]:PRESETS.dark[k]]))};}
export function buttonInk(hex){const rgb=hex.slice(1).match(/../g).map(x=>parseInt(x,16)/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4);return rgb[0]*.2126+rgb[1]*.7152+rgb[2]*.0722>.179?'#07101c':'#ffffff';}
export function loadTheme(){try{return normalizeTheme(JSON.parse(localStorage.getItem(KEY)));}catch{return normalizeTheme();}}
export function applyTheme(host,theme){if(!host)return;const c=theme.mode==='custom'?theme.colors:PRESETS[theme.mode];host.classList.add('themed-interface');host.dataset.interface=theme.mode;for(const [k,v] of Object.entries(c))host.style.setProperty('--ui-'+k,v);host.style.setProperty('--ui-button-text',buttonInk(c.button));}
export function themeEditor(theme){const shown=theme.mode==='custom'?theme.colors:PRESETS[theme.mode];return `<section class="palette-editor"><div><span class="eyebrow">ТВОЙ ИНТЕРФЕЙС</span><h2>Собери свою палитру.</h2><p>Бесплатное оформление меню и кнопок. Интерьер 3D-офиса выбирается ниже.</p></div><div class="palette-modes" role="group" aria-label="Тема интерфейса">${[['dark','Тёмная'],['light','Светлая'],['custom','Своя']].map(([id,label])=>`<button data-ui-mode="${id}" aria-pressed="${theme.mode===id}"><i class="palette-dot ${id}"></i>${label}</button>`).join('')}</div><div class="palette-colors">${Object.entries(FIELDS).map(([id,label])=>`<label>${label}<input type="color" data-ui-color="${id}" aria-label="${label}: выбрать цвет" value="${shown[id]}"><output data-ui-value="${id}">${shown[id]}</output></label>`).join('')}</div><div class="palette-preview"><div><small>ПРЕДПРОСМОТР</small><strong>Компания начинается с тебя.</strong><p>Цвета меняются сразу во всём тайконе.</p></div><button class="solid-button" type="button" data-ui-preview>Так выглядит кнопка ↗</button></div><div class="palette-footer"><span role="status" id="palette-status">Сохраняется автоматически на этом устройстве.</span><button data-ui-reset>Сбросить палитру</button></div></section>`;}
export function bindTheme(root,theme,{onChange=()=>{}}={}){const update=()=>{try{localStorage.setItem(KEY,JSON.stringify(theme));}catch{}applyTheme(root.querySelector('.tycoon-app'),theme);root.querySelectorAll('[data-ui-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.uiMode===theme.mode)));root.querySelectorAll('[data-ui-color]').forEach(input=>{input.value=(theme.mode==='custom'?theme.colors:PRESETS[theme.mode])[input.dataset.uiColor];root.querySelector(`[data-ui-value="${input.dataset.uiColor}"]`).textContent=input.value;});onChange(theme);};root.querySelectorAll('[data-ui-mode]').forEach(b=>b.onclick=()=>{theme.mode=b.dataset.uiMode;update();});root.querySelectorAll('[data-ui-color]').forEach(input=>input.oninput=()=>{if(theme.mode!=='custom')theme.colors={...PRESETS[theme.mode]};theme.mode='custom';theme.colors[input.dataset.uiColor]=input.value;update();});const reset=root.querySelector('[data-ui-reset]');if(reset)reset.onclick=()=>{theme.mode='dark';theme.colors={...PRESETS.dark};update();};const preview=root.querySelector('[data-ui-preview]');if(preview)preview.onclick=()=>{root.querySelector('#palette-status').textContent='Готово — эта палитра уже применяется к кнопкам тайкона.';};}
